sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float angle;
uniform float height;
uniform float radius;
uniform float keepColor;
uniform float brightness;
uniform float contrast;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float2 d = float2(cos(radians(angle)), sin(radians(angle))) * radius;
    float h = luma(tex(coord + d).rgb) - luma(tex(coord - d).rgb);
    float gray = (0.5 + h * height + brightness - 0.5) * contrast + 0.5;
    float3 o = mix(float3(gray), s * gray * 2.0, keepColor);
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
